      "svg": "<svg viewBox=\"0 0 1100 1100\"><rect width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"75\" font-size=\"28\" fill=\"#ffd700\" text-anchor=\"middle\" font-weight=\"bold\">The Hidden Risk in Hiring a 'One'</text><rect x=\"200\" y=\"170\" width=\"700\" height=\"140\" rx=\"12\" fill=\"#0ea5e9\" opacity=\"0.6\"/><text x=\"550\" y=\"230\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">Matching Title</text><text x=\"550\" y=\"270\" font-size=\"18\" fill=\"#ffffff\" text-anchor=\"middle\">looks like proof of capability</text><path d=\"M550,320 L550,400\" stroke=\"#ffd700\" stroke-width=\"5\"/><rect x=\"120\" y=\"420\" width=\"400\" height=\"200\" rx=\"12\" fill=\"#10b981\" opacity=\"0.6\"/><text x=\"320\" y=\"480\" font-size=\"19\" fill=\"#1a1a2e\" text-anchor=\"middle\">Genuine mastery:</text><text x=\"320\" y=\"515\" font-size=\"17\" fill=\"#1a1a2e\" text-anchor=\"middle\">specific decisions,</text><text x=\"320\" y=\"545\" font-size=\"17\" fill=\"#1a1a2e\" text-anchor=\"middle\">owns the trade-offs made</text><rect x=\"580\" y=\"420\" width=\"400\" height=\"200\" rx=\"12\" fill=\"#ef4444\" opacity=\"0.6\"/><text x=\"780\" y=\"480\" font-size=\"19\" fill=\"#ffffff\" text-anchor=\"middle\">Inherited advantage:</text><text x=\"780\" y=\"515\" font-size=\"17\" fill=\"#ffffff\" text-anchor=\"middle\">strong team, tailwinds,</text><text x=\"780\" y=\"545\" font-size=\"17\" fill=\"#ffffff\" text-anchor=\"middle\">predecessor's systems</text><text x=\"550\" y=\"700\" font-size=\"20\" fill=\"#ec4899\" text-anchor=\"middle\">Both can produce the same resume line</text><text x=\"550\" y=\"740\" font-size=\"20\" fill=\"#ec4899\" text-anchor=\"middle\">Only rigorous questioning tells them apart</text></svg>",
