      "svg": "<svg viewBox=\"0 0 1100 1100\"><rect width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"75\" font-size=\"27\" fill=\"#ffd700\" text-anchor=\"middle\" font-weight=\"bold\">Why Prior Training Falls Short</text><rect x=\"150\" y=\"170\" width=\"800\" height=\"140\" rx=\"12\" fill=\"#6366f1\" opacity=\"0.7\"/><text x=\"550\" y=\"230\" font-size=\"21\" fill=\"#ffffff\" text-anchor=\"middle\">General frameworks are taught</text><text x=\"550\" y=\"270\" font-size=\"21\" fill=\"#ffffff\" text-anchor=\"middle\">for typical situations</text><path d=\"M550,320 L550,400\" stroke=\"#f59e0b\" stroke-width=\"5\"/><text x=\"620\" y=\"370\" font-size=\"20\" fill=\"#f59e0b\">but</text><rect x=\"150\" y=\"420\" width=\"800\" height=\"140\" rx=\"12\" fill=\"#ef4444\" opacity=\"0.7\"/><text x=\"550\" y=\"475\" font-size=\"21\" fill=\"#ffffff\" text-anchor=\"middle\">Your problem is this exact company,</text><text x=\"550\" y=\"515\" font-size=\"21\" fill=\"#ffffff\" text-anchor=\"middle\">these exact people, this exact moment</text><path d=\"M550,570 L550,650\" stroke=\"#10b981\" stroke-width=\"5\"/><rect x=\"150\" y=\"670\" width=\"800\" height=\"160\" rx=\"12\" fill=\"#10b981\" opacity=\"0.7\"/><text x=\"550\" y=\"730\" font-size=\"21\" fill=\"#1a1a2e\" text-anchor=\"middle\">So knowledge must be actively built</text><text x=\"550\" y=\"770\" font-size=\"21\" fill=\"#1a1a2e\" text-anchor=\"middle\">on the job, in real time,</text><text x=\"550\" y=\"805\" font-size=\"21\" fill=\"#1a1a2e\" text-anchor=\"middle\">not assumed to already exist</text></svg>",
